        local done = false
        while not done do
            local line = self:at(from.line)
            local index = from.index
            while not done and index > 0 do
                index = index - 1
                if not CodePoint.isWhiteSpace(line[index + 1].codepoint) then
                    from.index = index
                    done = true
                end
            end
            if not done then
