        from = newDocPos(from.line, from.index)
        local done = false
        while not done do
            local line = self:at(from.line)
            local index = from.index
            while not done and index < #line do
                if CodePoint.isWhiteSpace(line[index + 1].codepoint) then
                    index = index + 1
                else
                    from.index = index
                    done = true
                end
